/* Wrap elke "o" in headings voor de Playfair-swap */
function initWrapLetterO() {
  const wrap = node => {
    if (node.nodeType === Node.TEXT_NODE) {
      const text = node.nodeValue;
      if (!/[oO]/.test(text)) return;

      const fragment = document.createDocumentFragment();
      for (const part of text.split(/([oO])/)) {
        if (/^[oO]$/.test(part)) {
          const span = document.createElement('span');
          span.className = 'playfair-o';
          span.textContent = part;
          fragment.append(span);
        } else fragment.append(document.createTextNode(part));
      }

      node.replaceWith(fragment);
    } else if (
      node.nodeType === Node.ELEMENT_NODE &&
      !node.matches('.playfair-o, script, style, svg')
    ) {
      [...node.childNodes].forEach(wrap);
    }
  };

  document.querySelectorAll('h1, h2, h3, h4, h5, h6, .nav-link:not([data-link-stagger])').forEach(wrap);
}

